function Invoke-CatalogSearch([string]$query){
  # ÑˆÐ°Ð³ 1: Search.aspx?q=... -> Ð½Ð°Ð¹Ð´Ñ‘Ð¼ download.aspx?...
  $u = "https://www.catalog.update.microsoft.com/Search.aspx?q=$([uri]::EscapeDataString($query))"
