  $hash = Get-SHA256 $cabPath

  # Ñ€Ð°ÑÐ¿Ð°ÐºÑƒÐµÐ¼ (Ð² Win10+ ÐµÑÑ‚ÑŒ expand.exe)
  $extDir = Join-Path $work "cab"
