function Select-BestDriver($items){
  if (-not $items) { return $null }
  # ÑÐ²Ñ€Ð¸ÑÑ‚Ð¸ÐºÐ°: Ð²Ñ‹Ð±Ð¸Ñ€Ð°Ñ‚ÑŒ Ð¿Ð¾ Ð´Ð°Ñ‚Ðµ/Ð²ÐµÑ€ÑÐ¸Ð¸ Ð² Title: Windows 10/11, x64
  $pref = @('Windows 11','Windows 10','x64','AMD64','64-bit')
  $scored = @()
  foreach($it in $items){
    $score = 0
    foreach($p in $pref){ if ($it.Title -match [Regex]::Escape($p)) { $score += 1 } }
    # Ñ‡ÐµÐ¼ Ð½Ð¾Ð²ÐµÐµ Ð¿Ð¾ Ñ‡Ð¸ÑÐ»Ð°Ð¼ Ð² Ð½Ð°Ð·Ð²Ð°Ð½Ð¸Ð¸ Ð²ÐµÑ€ÑÐ¸Ð¸ â€” Ñ‚ÐµÐ¼ Ð»ÑƒÑ‡ÑˆÐµ (Ð¾Ñ‡ÐµÐ½ÑŒ Ð³Ñ€ÑƒÐ±Ð¾)
    $vernums = ([regex]::Matches($it.Title, '\d+')) | ForEach-Object { [int]$_.Value }
